def earliest_arrival(n: int, connections: list[tuple[int, int, int, int]], source: int, target: int, start: int, change: int, max_transfers: int) -> int:
    if source == target:
        return start

    INF = float('inf')
    max_k = max_transfers + 1

    # dist[k][u] = 最早时刻: 恰好用 k 本便で駅 u にいる
    dist = [[INF] * n for _ in range(max_k + 1)]
    dist[0][source] = start

    for k in range(max_k):
        for u, v, depart, arrive in connections:
            cur = dist[k][u]
            if cur == INF:
                continue
            if k == 0:
                # 最初の 1 本: start <= depart で十分（乗り換え時間不要）
                if cur <= depart:
                    if arrive < dist[k + 1][v]:
                        dist[k + 1][v] = arrive
            else:
                # 2 本目以降: 到着時刻 + change <= depart
                if cur + change <= depart:
                    if arrive < dist[k + 1][v]:
                        dist[k + 1][v] = arrive

    ans = min(dist[k][target] for k in range(max_k + 1))
    return ans if ans != INF else -1
